window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[326]={"id":"326","numero":326,"titre":"Cadre réglementaire de la prescription","objectifs":[{"id":"326-1","rang":"A","rubrique":"Prise en charge","titre":"Connaître les différents cadres juridiques de prescription","contenu":"<p>La <span class=\"kw-def\">prescription</span> est un acte médical encadré par la loi. Son <span class=\"kw-def\">cadre juridique</span> fixe trois choses : faut-il une ordonnance pour obtenir le médicament, comment se fait le renouvellement, et où le médicament peut être prescrit et délivré.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">1 · Prescription facultative <span class=\"kw-bio\">vs</span> obl<span class=\"kw-chiffre\">iga</span>toire</h4>\n      <table >\n        <thead><tr><th>Cadre</th><th>Règles</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prescription médicale facultative</span></strong> (PMF)</td><td>Délivrables <strong>sans ordonnance</strong> ; peuvent malgré tout être prescrits (remboursement AM possible pour certains) ; <span class=\"kw-chiffre\">quantité limitée</span> lors d'un seul achat.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prescription médicale obligatoire</span></strong> (PMO)</td><td>Ordonnance exigée. Médicaments classés sur une <span class=\"kw-def\">liste de substances vénéneuses</span> et soumis, le cas échéant, à une <span class=\"kw-def\">prescription restreinte</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">2 · Listes des substances vénéneuses</h4>\n      <table >\n        <thead><tr><th>Liste</th><th>Renouvellement</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Liste I</span></strong></td><td><strong>Non renouvelable</strong>, sauf mention expresse du prescripteur : « à renouveler pendant X mois » ou « à renouveler Y fois ».</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Liste II</span></strong></td><td>Renouvellement <strong>automatique</strong>, sauf indication contraire du prescripteur.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stupéfiants</span></strong></td><td>Réglementation spécifique : <span class=\"kw-def\">ordonnance sécurisée</span>, <span class=\"kw-alerte\">renouvellement interdit</span> (détail ci-dessous, ex. des <span class=\"kw-ttt\">opioïdes</span>).</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">3 · Prescriptions restreintes</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Spécificité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Réserve hospitalière</span></td><td>Prescrit, délivré <em>et</em> administré uniquement en établissement de santé.</td></tr>\n          <tr><td><span class=\"kw-def\">Prescription hospitalière</span></td><td>Prescrit uniquement à l'hôpital, mais <strong>délivrable en ville</strong>.</td></tr>\n          <tr><td><span class=\"kw-def\">Prescription initiale hospitalière</span></td><td>La <strong>1ʳᵉ prescription</strong> doit être faite à l'hôpital ; renouvellement possible en ville.</td></tr>\n          <tr><td><span class=\"kw-def\">Réservée à certains spécialistes</span></td><td>Prescription réservée à des médecins spécialistes, à l'hôpital ou en ville.</td></tr>\n        </tbody>\n      </table>\n      <p>S'ajoutent : la <strong><span class=\"kw-def\">surveillance particulière</span></strong> (prescription subordonnée à des <span class=\"kw-bio\">examens périodiques</span> détaillés dans le <span class=\"kw-def\">RCP</span>, justifiés par la gravité des EI) ; <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">médicaments d'exception</span></strong> (chers, indications précises — pris en charge uniquement si la prescription respecte la <span class=\"kw-def\">fiche d'information thérapeutique</span> (FIT) produite par la HAS) ; les <strong><span class=\"kw-def\">préparations magistrales ou officinales</span></strong> (prise en charge soumise à la mention manuscrite « <em>prescription à but thérapeutique en l'absence de spécialités équivalentes disponibles</em> »).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">4 · Cas des stupéfiants (ex. des <span class=\"kw-ttt\">opioïdes</span>)</h4>\n      <table >\n        <thead><tr><th>Élément</th><th>Règle</th></tr></thead>\n        <tbody>\n          <tr><td>Ordonnance</td><td><strong><span class=\"kw-def\">Ordonnance sécurisée</span></strong> : papier filigrané, identification du prescripteur, n° du lot d'ordonnances, carré indiquant le nombre de médicaments prescrits.</td></tr>\n          <tr><td>Rédaction</td><td>Durée de traitement et nombre d'unités <strong>en toutes lettres</strong> ; voie d'administration précisée ; signature immédiatement sous la dernière ligne, espace résiduel rendu inutilisable.</td></tr>\n          <tr><td>Durée maximale</td><td><strong>Formes injectables immédiates :</strong> <span class=\"kw-chiffre\">7 jours</span><br><strong>Autres formes :</strong> <span class=\"kw-chiffre\">28 jours</span><br><strong>Fentanyl :</strong> prescription <span class=\"kw-chiffre\">28 jours</span>, délivrance fractionnée tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">14 jours</span> (transdermique) ou <span class=\"kw-chiffre\">7 jours</span> (transmuqueux)</td></tr>\n          <tr><td>Renouvellement</td><td><span class=\"kw-alerte\">Renouvellement interdit</span> ; <span class=\"kw-alerte\">chevauchement de 2 ordonnances interdit</span> (sinon mention « en <span class=\"kw-bio\">complément</span> de l'ordonnance du… »).</td></tr>\n          <tr><td>Délai de carence</td><td><span class=\"kw-chiffre\">3 jours</span> : au-delà, le pharmacien ne dispense que la quantité restant à couvrir jusqu'à la fin de la prescription.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">5 · L'ordonnance — mentions, validité, types</h4>\n      <p><strong>Mentions obl<span class=\"kw-chiffre\">iga</span>toires :</strong></p>\n      <ul>\n        <li>Identification complète du <strong>prescripteur</strong> et identité du <strong>patient</strong> (nom, âge, sexe ; poids et <span class=\"kw-bio\">DFG</span> si besoin)</li>\n        <li>Date de rédaction</li>\n        <li><strong><span class=\"kw-def\">Dénomination Commune Internationale</span></strong> (DCI) du médicament, ± nom de marque</li>\n        <li>Dosage, forme pharmaceutique, posologie et mode d'emploi</li>\n        <li>Durée du traitement ou nombre d'unités ; nombre de renouvellements</li>\n        <li>Mention « <span class=\"kw-alerte\">non remboursable</span> » (NR) si prescription hors-AMM</li>\n        <li>Signature sans espace après la dernière ligne (anti-rajout)</li>\n      </ul>\n      <p><strong>Validité :</strong> prescription renouvelable par périodes maximales de <span class=\"kw-chiffre\">1 mois</span> (ou <span class=\"kw-chiffre\">3 mois</span>), dans la limite de <span class=\"kw-chiffre\">12 mois</span> de traitement. L'ordonnance est <strong>caduque</strong> si non exécutée dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> suivant sa rédaction.</p>\n      <p><strong>Format :</strong> double exemplaire — l'original au <strong>patient</strong>, le duplicata à sa <strong>caisse d'assurance maladie</strong>.</p>\n      <p><strong>Types d'ordonnance :</strong> simple ; <span class=\"kw-def\">bizone</span> (patients en <span class=\"kw-def\">ALD</span>) ; <span class=\"kw-def\">sécurisée</span> (stupéfiants) ; d'<span class=\"kw-def\">exception</span> (produits et prestations d'exception).</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 321 — Bon usage du médoc et des thérapeutiques non médicamenteuses · 324 — Education thérap, observance et automédication</em></p>","frequence":1},{"id":"326-2","rang":"A","rubrique":"Prise en charge","titre":"Savoir expliquer la prescription d’un médicament générique ou d’un biosimilaire","contenu":"<p>La prescription d'un <span class=\"kw-def\">générique</span> ou d'un <span class=\"kw-def\">biosimilaire</span> obéit aux <strong>mêmes règles</strong> que celle du produit de référence (le <span class=\"kw-def\">princeps</span>).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Médicament générique</h4>\n      <p>Spécialité ayant <strong>même composition qualitative et quantitative</strong> en principes actifs, <strong>même forme pharmaceutique</strong>, et dont la <strong><span class=\"kw-def\">bioéquivalence</span></strong> avec le princeps est démontrée par des études appropriées (études <em>non requises</em> pour <span class=\"kw-clinique\">les</span> formes injectables et les médicaments à action locale).</p>\n      <table >\n        <thead><tr><th>Aspect</th><th>Règle — générique</th></tr></thead>\n        <tbody>\n          <tr><td>AMM</td><td><strong>AMM simplifiée</strong> : dispense de la démonstration d'efficacité et de sécurité (déjà faite par le princeps) ; dossier de qualité complet + démonstration de bioéquivalence exigés.</td></tr>\n          <tr><td>Délivrance</td><td>Le pharmacien peut substituer pour tout médicament inscrit au <span class=\"kw-def\">répertoire des génériques</span> de l'ANSM ; il doit indiquer sur l'ordonnance le nom du médicament délivré.</td></tr>\n          <tr><td>Substitution exclue par le prescripteur</td><td><strong>« non substituable (MTE) »</strong> — marge thérapeutique étroite<br><strong>« non substituable (EFG) »</strong> — enfant &lt; <span class=\"kw-chiffre\">6 ans</span> sans forme galénique générique adaptée<br><strong>« non substituable (CIF) »</strong> — CI formelle à un excipient à effet notoire présent dans tous <span class=\"kw-clinique\">les</span> génériques disponibles</td></tr>\n          <tr><td>Refus du patient</td><td>Le patient peut refuser la substitution : le remboursement se fait alors sur la base du <strong>prix du générique</strong>, pas du princeps délivré.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Médicament biosimilaire</h4>\n      <p>Médicament <strong>semblable à un médicament <span class=\"kw-ttt\">biologique</span> de référence</strong> déjà autorisé et dont le brevet est tombé dans le domaine public. On ne parle pas de « générique de biomédicament » : on ne peut jamais garantir que deux produits biologiques de même composition ont exactement <span class=\"kw-clinique\">les</span> mêmes effets biologiques.</p>\n      <table >\n        <thead><tr><th>Aspect</th><th>Règle — biosimilaire</th></tr></thead>\n        <tbody>\n          <tr><td>AMM</td><td>Accordée sur des données de <strong>qualité, sécurité et efficacité clinique</strong>, comparativement au médicament <span class=\"kw-ttt\">biologique</span> de référence.</td></tr>\n          <tr><td>Prescription</td><td>Prescrit en <strong><span class=\"kw-def\">DCI</span> ET nom de marque</strong> (ou de fantaisie).</td></tr>\n          <tr><td>Délivrance</td><td><span class=\"kw-alerte\">Pas de droit de substitution</span> du pharmacien d'officine — à la différence du générique.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> Le pharmacien peut substituer un <span class=\"kw-def\">générique</span> (répertoire ANSM), mais <span class=\"kw-alerte\">pas</span> un <span class=\"kw-def\">biosimilaire</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 321 — Bon usage du médoc et des thérapeutiques non médicamenteuses</em></p>","frequence":1},{"id":"326-3","rang":"B","rubrique":"Définition","titre":"Connaître la signification des indices de bénéfice clinique et d’intérêt thérapeutique : service médical rendu (SMR), amélioration du service médical rendu (ASMR)","contenu":"<p>Une fois l'<span class=\"kw-def\">AMM</span> obtenue, le médicament n'est pas pour autant remboursé : la <strong><span class=\"kw-def\">Commission de la transparence</span></strong> (CT) de la HAS l'évalue selon deux indices distincts — le <span class=\"kw-def\">SMR</span> et l'<span class=\"kw-def\">ASMR</span>.</p>\n\n      <table >\n        <thead><tr><th>Indice</th><th>Question posée</th><th>Détermine</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">SMR</span></strong><br>Service médical rendu</td><td>Le médicament a-t-il <strong>assez d'intérêt</strong> pour être pris en charge par la solidarité nationale ?</td><td>Le <strong>taux de remboursement</strong> (via l'UNCAM)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">ASMR</span></strong><br>Amélioration du SMR</td><td>Le médicament apporte-t-il un <strong>progrès</strong> par rapport aux traitements déjà disponibles ?</td><td>Le <strong>prix</strong> (via le CEPS)</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">SMR — <span class=\"kw-clinique\">les</span> 5 critères</h4>\n      <ul>\n        <li><strong>Rapport bénéfice/risque</strong> tel qu'estimé dans <span class=\"kw-clinique\">les</span> essais thérapeutiques</li>\n        <li><strong>Gravité de la maladie</strong> (<span class=\"kw-def\">morbidité</span>, mortalité, handicap, qualité de vie)</li>\n        <li><strong>Nature du traitement</strong> : curatif, préventif, substitutif, symptomatique, diagnostique</li>\n        <li><strong>Place dans la stratégie thérapeutique</strong> et existence d'alternatives</li>\n        <li><strong>Impact sur la santé publique</strong></li>\n      </ul>\n      <table >\n        <thead><tr><th>Niveau de SMR</th><th>Taux de remboursement (UNCAM)</th></tr></thead>\n        <tbody>\n          <tr><td>Majeur ou important</td><td><span class=\"kw-chiffre\">65 %</span>, voire <span class=\"kw-chiffre\">100 %</span> (ex. cancer, <span class=\"kw-etio\">VIH</span>)</td></tr>\n          <tr><td>Modéré</td><td><span class=\"kw-chiffre\">30 %</span></td></tr>\n          <tr><td>Faible</td><td><span class=\"kw-chiffre\">15 %</span></td></tr>\n          <tr><td>Insuffisant</td><td><span class=\"kw-alerte\">Avis défavorable au remboursement</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">ASMR — 5 niveaux</h4>\n      <p>L'<span class=\"kw-def\">ASMR</span> mesure la <strong>valeur ajoutée</strong> (efficacité + tolérance) du médicament par rapport aux produits déjà sur le marché. Cinq niveaux : <strong><span class=\"kw-chiffre\">I</span></strong> majeur, <strong><span class=\"kw-chiffre\">II</span></strong> important, <strong><span class=\"kw-chiffre\">III</span></strong> modéré, <strong><span class=\"kw-chiffre\">IV</span></strong> faible, <strong><span class=\"kw-chiffre\">V</span></strong> insuffisant (absence de progrès). Une ASMR élevée (I-II) autorise un prix supérieur aux alternatives ; une ASMR faible (IV-V) aligne le prix sur l'existant.</p>\n\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> <span class=\"kw-def\">SMR</span> → <strong>taux</strong> de remboursement. <span class=\"kw-def\">ASMR</span> → <strong>prix</strong>. SMR et prix sont réévalués <span class=\"kw-chiffre\">tous les 5 ans</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 323 — Utiliser <span class=\"kw-clinique\">les</span> résultats des études (analyse, recherche et niveau de preuve)</em></p>","frequence":1},{"id":"326-4","rang":"B","rubrique":"Définition","titre":"Connaître le rôle des professionnels impliqués dans l’exécution d’une prescription et leurs responsabilités légales et économiques","contenu":"<p>L'<strong>exécution d'une prescription</strong> — de la mise sur le marché du médicament à sa délivrance au patient — mobilise des acteurs institutionnels (régulation, prix, remboursement) et des professionnels de <span class=\"kw-def\">terrain</span> (prescripteur, pharmacien).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Acteurs institutionnels</h4>\n      <table >\n        <thead><tr><th>Acteur</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">ANSM</span></strong></td><td>Mise à disposition des produits de santé (<span class=\"kw-def\">AMM</span>, <span class=\"kw-def\">RTU</span>, <span class=\"kw-def\">ATU</span>, libération des lots et vaccins, dispositifs médicaux) ; <span class=\"kw-def\">réévaluation</span> de l'AMM ; conditions de prescription/délivrance ; surveillance ; inspection des établissements ; contrôle de la publicité. <em>Responsabilité sanitaire et légale.</em></td></tr>\n          <tr><td><strong><span class=\"kw-def\">HAS</span></strong></td><td>Évaluation médicale et économique des produits de santé en vue du remboursement. Sa <strong>Commission de la transparence</strong> évalue <span class=\"kw-clinique\">les</span> médicaments et détermine le <span class=\"kw-def\">SMR</span> et l'<span class=\"kw-def\">ASMR</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">CEPS</span></strong></td><td>Comité économique des produits de santé : <strong>fixe le prix</strong> des médicaments et le tarif des dispositifs médicaux pris en charge. <em>Responsabilité économique.</em></td></tr>\n          <tr><td><strong><span class=\"kw-def\">UNCAM</span></strong></td><td>Union nationale des caisses d'assurance maladie : définit le champ des prestations remboursées et <strong>fixe le taux de remboursement</strong>, sur la base du SMR. <em>Responsabilité économique.</em></td></tr>\n          <tr><td><strong>Ministère</strong> (Santé / Sécurité sociale)</td><td><strong>Décision finale d'AMM française</strong> et <strong>décision d'inscription au remboursement</strong> → publiée au Journal Officiel.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Circuit du remboursement</h4>\n      <p>L'AMM n'est <span class=\"kw-alerte\">pas synonyme</span> de prise en charge par la collectivité. Pour qu'un médicament soit remboursable :</p>\n      <ul>\n        <li>L'entreprise dépose une demande à la <strong>HAS</strong></li>\n        <li>La <strong>Commission de la transparence</strong> rend un avis (<span class=\"kw-def\">SMR</span> + <span class=\"kw-def\">ASMR</span>)</li>\n        <li>Avis transmis à l'<strong>UNCAM</strong> (fixe le taux, sur le SMR) et au <strong>CEPS</strong> (fixe le prix, sur l'ASMR)</li>\n        <li><span class=\"kw-clinique\">Les</span> <strong>ministres</strong> chargés de la Santé et de la Sécurité sociale prennent la décision finale d'inscription</li>\n        <li><span class=\"kw-def\">Réévaluation</span> <span class=\"kw-chiffre\">tous les 5 ans</span></li>\n      </ul>\n      <p>À la différence de l'AMM (majoritairement <strong>européenne</strong>), le remboursement est un processus <strong>spécifiquement français</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Professionnels de l'exécution</h4>\n      <ul>\n        <li><strong>Prescripteur</strong> — responsable de la prescription : choix du médicament, mentions obl<span class=\"kw-chiffre\">iga</span>toires de l'ordonnance, possibilité d'exclure la substitution.</li>\n        <li><strong>Pharmacien d'officine</strong> — responsable de la dispensation : droit de substitution par un générique (avec indication du nom délivré), respect du délai de carence des stupéfiants, conseil au patient.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Si un médicament est jugé <span class=\"kw-alerte\">non remboursable</span> par la CT de la HAS, son <strong>prix est fixé librement par <span class=\"kw-clinique\">les</span> pharmaciens d'officine</strong>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 321 — Bon usage du médoc et des thérapeutiques non médicamenteuses</em></p>","frequence":0},{"id":"326-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître le rapport bénéfice / risque et bénéfice net à partir des informations disponibles","contenu":"<p>Cet objectif de rang A porte sur l'analyse du <span class=\"kw-def\">rapport bénéfice/risque</span> et du <span class=\"kw-def\">bénéfice net</span> d'un médicament à partir des informations disponibles (essais, <span class=\"kw-def\">RCP</span>, méta-analyses).</p>\n      <p><span class=\"kw-clinique\">Les</span> fiches sources du dossier <code>326-cardre-reglementaire-prescriptio/</code> ne traitent ce point qu'<strong>indirectement</strong> : le <span class=\"kw-def\">rapport bénéfice/risque</span> n'y apparaît que comme l'un des <strong>5 critères du SMR</strong>, « tel qu'estimé dans les essais thérapeutiques » (voir l'objectif SMR / ASMR).</p>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucun développement dédié à l'analyse du rapport bénéfice/risque et du bénéfice <span class=\"kw-alerte\">net</span> n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources de cet item. Kevin enrichira ce paragraphe à partir du Collège de thérapeutique ou d'une recherche ciblée (notion de bénéfice net, balance attendue/observée, transposabilité des essais à la pratique).</div>\n      <!-- TODO Kevin : rédiger l'analyse bénéfice/risque + bénéfice net -->\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 321 — Bon usage du médoc et des thérapeutiques non médicamenteuses · 322 — Décision thérapeutique personnalisée</em></p>","frequence":0},{"id":"326-6","rang":"B","rubrique":"Définition","titre":"Connaître la définition du développement professionnel continu sur le médicament : apprécier la source et la fiabilité des informations","contenu":"<p>Apprécier la <strong>fiabilité d'une information</strong> sur le médicament, c'est savoir d'où elle vient et sur quel niveau de preuve elle repose. <span class=\"kw-clinique\">Les</span> deux repères centraux sont les <span class=\"kw-def\">recommandations de bonnes pratiques</span> (RBP) et le <span class=\"kw-def\">niveau de preuve</span> des études.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Recommandations de bonnes pratiques (RBP)</h4>\n      <p>Élaborées par la <strong>HAS</strong> (auto-saisine, ou demande d'un conseil professionnel, d'une société savante, d'une agence sanitaire, d'une caisse d'assurance maladie…). Trois méthodes sont promues par la HAS :</p>\n      <table >\n        <thead><tr><th>Méthode</th><th>Quand l'employer</th><th>Durée</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">RPC</span></strong> — recommandations pour la pratique clinique <em>(méthode préférentielle)</em></td><td>Thématique large ; données cliniques disponibles mais dispersées ; controverse modérée, sans débat public.</td><td><span class=\"kw-chiffre\">12 à 18 mois</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">RCF</span></strong> — recommandations par consensus formalisé</td><td>Données rares, absentes ou contradictoires ; controverse nécessitant une formalisation et des accords professionnels.</td><td><span class=\"kw-chiffre\">6 à 12 mois</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">CdC</span></strong> — conférence de consensus</td><td>Données rares ; controverse majeure nécessitant un débat public et un jury de non-experts.</td><td><span class=\"kw-chiffre\">9 à 18 mois</span></td></tr>\n        </tbody>\n      </table>\n      <p>Toute RBP est précédée d'une <strong>phase de cadrage</strong> aboutissant à une <span class=\"kw-def\">note de cadrage</span> (feuille de route de l'ensemble du processus).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Niveau de preuve et gradation</h4>\n      <table >\n        <thead><tr><th>Niveau</th><th>Type d'étude</th><th><span class=\"kw-def\">Grade</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">Niveau 1</span></td><td>Essais comparatifs randomisés de forte puissance ; méta-analyses d'essais randomisés</td><td><strong><span class=\"kw-def\">Grade A</span></strong> — preuve scientifique établie</td></tr>\n          <tr><td><span class=\"kw-chiffre\">Niveau 2</span></td><td>Essais randomisés de faible puissance ; études comparatives non randomisées bien menées ; cohortes prospectives</td><td><strong><span class=\"kw-def\">Grade B</span></strong> — présomption scientifique</td></tr>\n          <tr><td><span class=\"kw-chiffre\">Niveau 3</span></td><td>Études cas-témoins</td><td><strong><span class=\"kw-def\">Grade C</span></strong> — faible niveau de preuve</td></tr>\n          <tr><td><span class=\"kw-chiffre\">Niveau 4</span></td><td>Études comparatives avec biais importants ; études rétrospectives ; séries de cas ; études descriptives</td><td><strong><span class=\"kw-def\">Grade C</span></strong></td></tr>\n        </tbody>\n      </table>\n      <p>Le niveau de preuve d'une étude dépend de : schéma de l'étude, adéquation à la question posée, adaptation de l'analyse statistique, existence de <strong>biais</strong>, puissance et taille d'échantillon.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le niveau de preuve <span class=\"kw-alerte\">ne dépend PAS</span> : du caractère supériorité / non-infériorité de l'étude, du résultat positif ou négatif, ni de la pertinence clinique du <span class=\"kw-def\">critère de</span> jugement. En l'absence de preuve, un <strong>accord d'experts</strong> requiert l'approbation de <span class=\"kw-chiffre\">≥ 80 %</span> du groupe de travail.</div>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Toutes <span class=\"kw-clinique\">les</span> études rétrospectives sont de <span class=\"kw-chiffre\">niveau 4</span>, <strong>sauf l'étude cas-témoin</strong> (<span class=\"kw-chiffre\">niveau 3</span>).</div>\n\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La définition institutionnelle du <span class=\"kw-def\">développement professionnel continu</span> (DPC — dispositif d'obl<span class=\"kw-chiffre\">iga</span>tion de formation continue des professionnels de santé) n'est pas développée dans <span class=\"kw-clinique\">les</span> fiches sources de cet item. Kevin la complétera depuis le Collège.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 323 — Utiliser <span class=\"kw-clinique\">les</span> résultats des études (analyse, recherche et niveau de preuve)</em></p>","frequence":0},{"id":"326-7","rang":"B","rubrique":"Prise en charge","titre":"Tenir compte de la situation individuelle du patient pour ajuster le rapport bénéfice/risque en vue de la prescription","contenu":"<p>Cet objectif de rang B porte sur l'<strong>individualisation de la prescription</strong> : ajuster le <span class=\"kw-def\">rapport bénéfice/risque</span> à la situation propre du patient (âge, <span class=\"kw-def\">comorbidités</span>, fonction rénale et hépatique, <span class=\"kw-ci\">grossesse</span>, traitements associés, préférences) avant de prescrire.</p>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> Aucun contenu correspondant à cet objectif n'a été trouvé dans <span class=\"kw-clinique\">les</span> fiches sources du dossier <code>326-cardre-reglementaire-prescriptio/</code>. Kevin enrichira ce paragraphe — la matière est largement traitée dans l'item 322 (Décision thérapeutique personnalisée), à mobiliser comme source principale.</div>\n      <!-- TODO Kevin : rédiger l'ajustement du bénéfice/risque à la situation individuelle -->\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 322 — Décision thérapeutique personnalisée</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"3dd6dc64ba8f","n":326,"o":"326-1","u":"Prise en charge","t":"Connaître les différents cadres juridiques de prescription","q":"Quelles sont les spécificités de la prescription médicale des stupéfiants (par exemple, les opioïdes) ?","a":"<ul><li><strong>Ordonnance</strong> : Elle doit être <strong>sécurisée</strong> (papier filigrané, identification du prescripteur, numéro de lot, carré pour le nombre de médicaments).</li><li><strong>Rédaction</strong> : La durée de traitement et le nombre d'unités doivent être écrits <strong>en toutes lettres</strong> ; la voie d'administration doit être précisée ; signature juste sous la dernière ligne.</li><li><strong>Durée maximale</strong> : Les formes injectables immédiates sont limitées à <strong>7 jours</strong>. Les autres formes sont limitées à <strong>28 jours</strong> (sauf fentanyl avec délivrance fractionnée).</li><li><strong>Renouvellement</strong> : Le renouvellement est <strong>interdit</strong> et le chevauchement de deux ordonnances également.</li><li><strong>Délai de carence</strong> : Au-delà de <strong>3 jours</strong>, le pharmacien ne délivre que la quantité restante.</li></ul>"},{"i":"5fd9428a3d1f","n":326,"o":"326-1","u":"Prise en charge","t":"Connaître les différents cadres juridiques de prescription","q":"Quelles sont les mentions obligatoires d'une ordonnance médicale en France ?","a":"<ul><li>Identification complète du <strong>prescripteur</strong> et du <strong>patient</strong> (nom, âge, sexe, éventuellement poids et DFG).</li><li><strong>Date de rédaction</strong>.</li><li><strong>Dénomination Commune Internationale (DCI)</strong> du médicament, et éventuellement le nom de marque.</li><li><strong>Dosage, forme pharmaceutique, posologie et mode d'emploi</strong>.</li><li><strong>Durée du traitement</strong> ou nombre d'unités, et le nombre de renouvellements.</li><li>Mention <strong>« non remboursable » (NR)</strong> si prescription hors-AMM.</li><li><strong>Signature</strong> sans espace après la dernière ligne.</li></ul>"},{"i":"6a21d87eea21","n":326,"o":"326-1","u":"Prise en charge","t":"Connaître les différents cadres juridiques de prescription","q":"Quelles sont les règles de renouvellement des ordonnances pour les médicaments classés Liste I, Liste II et les stupéfiants ?","a":"<ul><li><strong>Liste I</strong> : La prescription est <strong>non renouvelable</strong>, sauf mention expresse du prescripteur (ex: « à renouveler pendant X mois » ou « à renouveler Y fois »).</li><li><strong>Liste II</strong> : Le renouvellement est <strong>automatique</strong>, sauf indication contraire du prescripteur.</li><li><strong>Stupéfiants</strong> : Ils suivent une réglementation spécifique nécessitant une <strong>ordonnance sécurisée</strong> et un renouvellement est <strong>interdit</strong>.</li></ul>"},{"i":"896d1525bf91","n":326,"o":"326-1","u":"Prise en charge","t":"Connaître les différents cadres juridiques de prescription","q":"Quels sont les différents types de prescriptions restreintes et leurs caractéristiques principales ?","a":"<ul><li><strong>Réserve hospitalière</strong> : Prescrit, délivré et administré <strong>uniquement en établissement de santé</strong>.</li><li><strong>Prescription hospitalière</strong> : Prescrit <strong>uniquement à l'hôpital</strong>, mais peut être délivré en ville.</li><li><strong>Prescription initiale hospitalière</strong> : La première prescription doit être faite à l'hôpital ; le renouvellement est ensuite possible en ville.</li><li><strong>Réservée à certains spécialistes</strong> : Prescription limitée à des médecins spécialistes, à l'hôpital ou en ville.</li></ul>"},{"i":"e6c2ca3e73cc","n":326,"o":"326-1","u":"Prise en charge","t":"Connaître les différents cadres juridiques de prescription","q":"Comment diffère la Prescription Médicale Facultative (PMF) de la Prescription Médicale Obligatoire (PMO) en France ?","a":"<p>La <strong>Prescription Médicale Facultative (PMF)</strong> concerne les médicaments délivrables <strong>sans ordonnance</strong>, bien qu'ils puissent être prescrits pour un éventuel remboursement. La quantité est limitée par achat.</p><p>La <strong>Prescription Médicale Obligatoire (PMO)</strong> exige impérativement une <strong>ordonnance</strong>, notamment pour les médicaments classés sur une liste de substances vénéneuses ou soumis à des restrictions de prescription.</p>"},{"i":"0c36c0adabe1","n":326,"o":"326-2","u":"Prise en charge","t":"Savoir expliquer la prescription d’un médicament générique ou d’un biosimilaire","q":"Quelles sont les spécificités de l'<strong>Autorisation de Mise sur le Marché (AMM)</strong> d'un <strong>médicament générique</strong> par rapport à celle du princeps ?","a":"<p>L'AMM d'un générique est une <strong>AMM simplifiée</strong>. Elle dispense de la démonstration d'efficacité et de sécurité (déjà établie par le princeps). Cependant, un <strong>dossier de qualité complet</strong> et une <strong>démonstration de bioéquivalence</strong> sont exigés, sauf pour les formes injectables et les médicaments à action locale.</p>"},{"i":"16486f7184bb","n":326,"o":"326-2","u":"Prise en charge","t":"Savoir expliquer la prescription d’un médicament générique ou d’un biosimilaire","q":"Quelle est la définition d'un <strong>médicament biosimilaire</strong> ?","a":"<p>Un médicament biosimilaire est un médicament <strong>semblable à un médicament biologique de référence</strong> déjà autorisé et dont le brevet est tombé dans le domaine public.</p>"},{"i":"36caeedca06e","n":326,"o":"326-2","u":"Prise en charge","t":"Savoir expliquer la prescription d’un médicament générique ou d’un biosimilaire","q":"Comment est défini un <strong>médicament générique</strong> en droit pharmaceutique français ?","a":"<p>Un médicament générique est une spécialité ayant la <strong>même composition qualitative et quantitative en principes actifs</strong>, la <strong>même forme pharmaceutique</strong>, et dont la <strong>bioéquivalence</strong> avec le princeps est démontrée par des études appropriées.</p>"},{"i":"a77518c9393c","n":326,"o":"326-2","u":"Prise en charge","t":"Savoir expliquer la prescription d’un médicament générique ou d’un biosimilaire","q":"Le pharmacien d'officine a-t-il un <strong>droit de substitution</strong> pour un <strong>médicament biosimilaire</strong> ?","a":"<p>Non, le pharmacien d'officine n'a <strong>pas le droit de substituer</strong> un médicament biosimilaire, contrairement au médicament générique.</p>"},{"i":"ca001f8d6e5e","n":326,"o":"326-2","u":"Prise en charge","t":"Savoir expliquer la prescription d’un médicament générique ou d’un biosimilaire","q":"Dans quels cas précis le prescripteur peut-il <strong>refuser la substitution</strong> d'un princeps par un <strong>médicament générique</strong> en France ?","a":"<ul><li><strong>Marge thérapeutique étroite (MTE)</strong>, avec la mention \"non substituable (MTE)\".</li><li><strong>Enfant de moins de 6 ans</strong> sans forme galénique générique adaptée, avec la mention \"non substituable (EFG)\".</li><li><strong>Contre-indication formelle (CIF)</strong> à un excipient à effet notoire présent dans tous les génériques disponibles, avec la mention \"non substituable (CIF)\".</li></ul>"},{"i":"e2defb5f12f5","n":326,"o":"326-2","u":"Prise en charge","t":"Savoir expliquer la prescription d’un médicament générique ou d’un biosimilaire","q":"Quelles sont les règles de <strong>prescription</strong> d'un <strong>médicament biosimilaire</strong> en France ?","a":"<p>Le médicament biosimilaire doit être prescrit en mentionnant à la fois la <strong>Dénomination Commune Internationale (DCI)</strong> et le <strong>nom de marque</strong> (ou de fantaisie).</p>"},{"i":"f9d837571745","n":326,"o":"326-2","u":"Prise en charge","t":"Savoir expliquer la prescription d’un médicament générique ou d’un biosimilaire","q":"Quel est l'impact du <strong>refus de substitution</strong> par le patient concernant un <strong>médicament générique</strong> sur son remboursement ?","a":"<p>Si le patient refuse la substitution par un générique, le remboursement se fera sur la base du <strong>prix du générique</strong>, et non du princeps délivré.</p>"},{"i":"199f732daccc","n":326,"o":"326-5","u":"Prise en charge","t":"Connaître le rapport bénéfice / risque et bénéfice net à partir des informations disponibles","q":"Comment est défini le rapport bénéfice/risque d'un médicament dans le cadre du Service Médical Rendu (SMR) ?","a":"<p>Dans le cadre du SMR, le rapport bénéfice/risque est défini comme l'un des <strong>cinq critères</strong> d'évaluation, tel qu'estimé à partir des <strong>essais thérapeutiques</strong> réalisés.</p>"},{"i":"39200e3f2661","n":326,"o":"326-5","u":"Prise en charge","t":"Connaître le rapport bénéfice / risque et bénéfice net à partir des informations disponibles","q":"Quelles sont les sources d'information principales utilisées pour évaluer le rapport bénéfice/risque d'un médicament ?","a":"<ul><li>Les <strong>essais cliniques</strong> (randomisés, contrôlés) fournissent les données initiales sur l'efficacité et la sécurité.</li><li>Le <strong>Résumé des Caractéristiques du Produit (RCP)</strong> fournit des informations officielles et détaillées sur le médicament.</li><li>Les <strong>méta-analyses</strong> permettent de synthétiser les résultats de plusieurs études pour une vision globale.</li></ul>"},{"i":"ac2d5aa2ad3f","n":326,"o":"326-5","u":"Prise en charge","t":"Connaître le rapport bénéfice / risque et bénéfice net à partir des informations disponibles","q":"Quelle est la différence entre le rapport bénéfice/risque attendu et le rapport bénéfice/risque observé d'un médicament ?","a":"<p>Le rapport bénéfice/risque <strong>attendu</strong> est celui estimé à partir des données des essais cliniques et pré-commercialisation. Le rapport bénéfice/risque <strong>observé</strong> est celui constaté en vie réelle après commercialisation, tenant compte de l'utilisation du médicament dans une population plus hétérogène et sur une plus longue période.</p>"}]};